\label[assumption]{ass:affine_decomp_param_Lindbladian}
For a compact domain $\mathcal{P}\subseteq\ensuremath\mathbb{R}^d$, the parametric
Lindbladian $\mathcal{L}:\mathcal{P}\to\mathcal B(\mathcal H)$ has the form
\begin{equation}
\mathcal{L}(\mu)X
=
\sum_{p=1}^{P}
\theta_p(\mu) \mathcal{K}_p(X)
+
\sum_{q=1}^{Q}
\phi_q(\mu)\mathcal D_q(X),
\label{eq:Lindbladian_affine_decomposition}
\end{equation}
where 
\begin{align*}
\mathcal{K}_p(X)
\coloneqq \, 
-\mathrm{i} \big[ H_p, X \big]
\qquad \text{and} \qquad
\mathcal D_q(X)
& \coloneqq \, 
\sum_{\ell=1}^{m_q}
\bigl(
L_{q,\ell}XL_{q,\ell}^\dagger
-
\frac12
\{L_{q,\ell}^\dagger L_{q,\ell},X\}
\bigr)
\end{align*}
for $p=1,\ldots,P$ and $q=1,\ldots,Q$,
with each $H_p\in\mathcal H$ 
and $L_{q,\ell}\in\ensuremath\mathbb{C}^{N\timesN}$ fixed.
The coefficient functions
$\theta_p:\mathcal{P}\to\ensuremath\mathbb{R}$ and
$\phi_q:\mathcal{P}\to[0,\infty)$ are also fixed scalar functions.

\label[definition]{def:sol_set}
For $\mathcal{L}: \mathcal{P} \to \mathcal{B}(\mathcal{H})$ as in \Cref{ass:affine_decomp_param_Lindbladian},
its {\emph{steady state solution set}} is defined as 
\begin{align*} 
\mathcal{M} \; \coloneqq \; \{ \rho \in S \, | \, \exists \mu \in \mathcal{P} : \mathcal{L}(\mu) \rho = 0 \}. 
\end{align*}
The \emph{Kolmogorov-$n$-width} of $\mathcal{M}$ is defined as 
\begin{align*}
d_n(\mathcal{M})
\;\coloneqq
\inf_{\substack{V\subseteq\mathcal H\\ \dim V\leq n}}
\sup_{\rho \in \mathcal{M}}
\mathrm{dist}(\rho,V)
\qquad \text{for } n\in \ensuremath\mathbb{N}.
\end{align*}

\label[lemma]{lem:beta_gap_angle_relation}
For every $\mu\in\mathcal{P}$, it holds that
\begin{equation}
    \beta(\mu)
\geq
\sqrt{\gamma(\mu)}\sin\psi(\mu).
\label{eq:beta_gamma_angle_rel}
\end{equation}
If $\mathcal{L}(\mu)$ has a unique steady state, 
then it holds that 
\begin{equation*}
\sin\psi(\mu)
=
\frac{1}{\sqrt{N}\,\|\rho_{\mathrm{ss}}(\mu)\|}
\in
\left[\frac{1}{\sqrt{N}},1\right]
\qquad \text{and} \qquad
\beta(\mu)
\geq
\frac{\sqrt{\gamma(\mu)}}
{\sqrt{N}\,\|\rho_{\mathrm{ss}}(\mu)\|}
\geq
\sqrt{\frac{\gamma(\mu)}{N}}.
\end{equation*}

\label[proposition]{prop:generic_residual_state_error}
Let $\mu\in \mathcal{P}$ satisfy $\dim \ker\mathcal{L}(\mu) = 1$, 
and let $X\in\mathcal H$ satisfy $\operatorname{tr} X\neq0$. 
Then, it holds that 
\begin{equation*}
\Bigl\|
\rho_{\mathrm{ss}}(\mu)
-
\frac{X}{\operatorname{tr} X}
\Bigr\|
\,\leq\,
\frac{
\|\mathcal{L}(\mu)X\|
}{
\beta(\mu)|\operatorname{tr} X|
}.
\end{equation*}

\label[corollary]{cor:online_approx_steady_state_error}
Let $\mu\in \mathcal{P}$ satisfy $\dim \ker \mathcal{L}(\mu) =1$.
Let $V \subseteq \mathcal{H}$ be an RB space constructed by one of the methods in \Cref{subsubsec:POD_vs_greedy}.
Consider $ \rho_{\mathrm{aff}}^{(r)}(\mu) $
from \eqref{eq:reduced_affine_approximation},
and assume that $ \rho_{\mathrm{eig}}^{(r)}(\mu)$ from \eqref{eq:trace_normalized_reduced_eigenvector} is well-defined. 
For $\star \in \{ \mathrm{eig}, \mathrm{aff}\}$, 
it holds that 
\begin{equation*}
\|
\rho_{\mathrm{ss}}(\mu)-\rho_{\star}^{(r)}(\mu)
\|
\,\leq\,
\frac{
\|\mathcal{L}(\mu)\rho_{\star}^{(r)}(\mu)\|
}{
\beta(\mu)
}.
\end{equation*}

\label[theorem]{thm:weak_greedy_convergence_rates}
Suppose there exists a \emph{solution map} $u:\mathcal{P}\to\mathcal H$,
such that the solution set $\mathcal M=u(\mathcal{P})$ is compact and contained
in the closed unit ball of~$\mathcal H$.
Let $(\mu_r)_{r\in \ensuremath\mathbb{N}}$ be a sequence of snapshot parameters and 
$(V_r)_{r\in \ensuremath\mathbb{N}}$  a sequence of RB spaces, 
so that
$V_{r+1}
=
V_r+\operatorname{span}_{\ensuremath\mathbb{R}}\{u(\mu_{r})\}.$
Moreover, assume that the following conditions hold:
\begin{enumerate}
\item \label{item:weak_greedy}
\emph{(Weak greedy selection)}
Suppose that there exists a constant $\vartheta\in(0,1]$,
called the \emph{weakness parameter}, 
such that
\begin{equation*}
\mathrm{dist}(u(\mu_r), V_r)
\, \geq \, 
\vartheta
\sup_{\mu\in\mathcal{P}}
\mathrm{dist}(u(\mu), V_r)
\qquad \text{for all }
r \in \ensuremath\mathbb{N}.
\end{equation*}
\item \label{item:rate_decay} 
\emph{(Decaying Kolmogorov-$n$-width)}
There exist constants $\alpha_0, \alpha_1,\alpha_2>0$, such that
\[
d_n(\mathcal M)
\, \leq \,
\alpha_0 \exp \bigl(-\alpha_1 n^{\alpha_2} \bigr)
\qquad
\text{for all }n\in \ensuremath\mathbb{N},
\]
where $d_n(\mathcal M)$ is the Kolmogorov-$n$-width of $\mathcal{M}$ from \Cref{def:sol_set}.

\end{enumerate}
Then, with $C_1 \coloneqq \sqrt{2 \alpha_0} / \vartheta$ and
$C_2 \coloneqq 2^{-1-2\alpha_2}\alpha_1$, 
it holds that
\begin{equation}
\sup_{\mu\in\mathcal{P}}
\mathrm{dist}\bigl(u(\mu),V_{1+r}\bigr)
\,\leq\,
C_1\exp\bigl(-C_2\,  r^{\alpha_2}\bigr)
\qquad\text{for all }r\in\ensuremath\mathbb{N}.
\label{eq:weak_greedy_exponential_rate}
\end{equation}
In particular, the greedy procedure converges at an exponential rate if $\alpha_2=1$, 
or at a sub-exponential rate if $0<\alpha_2<1$.

\label[assumption]{ass:continuous_wellposedness}
The following conditions hold:
\begin{enumerate}
\item
The coefficient functions
$\theta_1,\ldots,\theta_P,\phi_1,\ldots,\phi_Q$
from \Cref{ass:affine_decomp_param_Lindbladian}
are continuous on~$\mathcal{P}$. 
\item
$\mathcal{L}(\mu)$ has a unique steady state for every
$\mu\in\mathcal{P}$. 
\end{enumerate}

\label{prp:valid_weak_greedy}
Suppose \Cref{ass:continuous_wellposedness} holds,
and let $V_r\subseteq\mathcal H$ be a reduced space satisfying $I\in V_r$. 
Then, the constants 
\begin{align*}
\varrho_{\max}
&\coloneqq
\max_{\mu\in\mathcal{P}}
\max_{\|X\|=1}
\langle X,\mathcal A(\mu)X\rangle,
&
\gamma_{\min}
&\coloneqq
\min_{\mu\in\mathcal{P}}\gamma(\mu),
\\
\nu_{\min}
&\coloneqq
\min_{\mu\in\mathcal{P}}\|\rho_{\mathrm{ss}}(\mu)\|^2,
&
\beta_{\min}
&\coloneqq
\min_{\mu\in\mathcal{P}}\beta(\mu).
\end{align*}
 are well-defined and satisfy
$0<\varrho_{\max}<\infty$, $\gamma_{\min}>0$,
$\nu_{\min}>0$, and $\beta_{\min}>0$.
Furthermore, the following properties hold true for any $r\in \mathbb{N}$.
\begin{enumerate}
\item 
\label{item:eig_formulation_error_equivalence} 
For $\Delta^{(r)}_\mathrm{eig}$ from \eqref{eq:eigenvalue_error_indicator},
we have 
\begin{equation*}
\nu_{\min}\varrho_{\max}^{-1}
\Delta^{(r)}_\mathrm{eig}(\mu)
\, \leq \, 
\mathrm{dist}(\rho_{\mathrm{ss}}(\mu), V_r)^2
\, \leq \, 
\gamma_{\min}^{-1}
\Delta^{(r)}_\mathrm{eig}(\mu)
\qquad \text{for all }
\mu \in \mathcal{P}.
\end{equation*}
\item 
\label{item:aff_formulation_error_equivalence} 
For $\Delta^{(r)}_\mathrm{aff}$ from \eqref{eq:affine_error_indicator},
we have  
\begin{equation*}
\varrho_{\max}^{-1}
\Delta^{(r)}_\mathrm{aff}(\mu)
\, \leq \, 
\mathrm{dist}(\rho_{\mathrm{ss}}(\mu), V_r)^2
\, \leq \, 
\beta_{\min}^{-2}
\Delta^{(r)}_\mathrm{aff}(\mu)
\qquad \text{for all }
\mu \in \mathcal{P}.
\end{equation*}
\end{enumerate}

\label[assumption]{ass:real_analytic_parameter_dependence}
There exists an open neighborhood $\Omega\subseteq\ensuremath\mathbb{R}^d$ of $\mathcal{P}$,
such that each coefficient function
$\theta_1,\ldots,\theta_P,\phi_1,\ldots,\phi_Q$
from \Cref{ass:affine_decomp_param_Lindbladian}
admits a real-analytic extension to~$\Omega$.

\label[proposition]{prop:analytic_width_decay}
Suppose the assumptions of \Cref{prop:analyticity_steady_state_map} hold,
and suppose additionally that
\begin{equation*}
\mathcal{P}
=
[a_1,b_1]\times \cdots \times[a_d,b_d]
\qquad\text{with}\qquad
a_j<b_j
\quad\text{for }j=1,\ldots,d.
\end{equation*}
Then there exist constants $\alpha_0,\alpha_1>0$ such that
\begin{equation}
d_n(\mathcal M)
\,\leq\,
\alpha_0\exp\Bigl(-\alpha_1 n^{1/d}\Bigr)
\qquad\text{for all }n\in\ensuremath\mathbb{N}.
\label{eq:generalized_exponential_width_decay}
\end{equation}

\label[corollary]{cor:idealized_greedy_convergence}
Suppose the assumptions of \Cref{prop:analytic_width_decay} hold.
For $\star\in\{\mathrm{eig},\mathrm{aff}\}$,
let $V_{1,\star}\coloneqq\operatorname{span}_\ensuremath\mathbb{R}\{I\}$ and suppose the sequence of reduced spaces is generated by
\begin{equation*}
\mu_{r,\star}
\,\in\,
\operatorname*{arg\,max}_{\mu\in\mathcal{P}}
\Delta_\star^{(r)}(\mu),
\qquad
V_{r+1,\star}
=
V_{r,\star}
+
\operatorname{span}_\ensuremath\mathbb{R}\{\rho_{\mathrm{ss}}(\mu_{r,\star})\}
.
\end{equation*}
Then there exist $C_1,C_2>0$, 
such that
\begin{equation*}
\sup_{\mu\in\mathcal{P}}
\mathrm{dist}\bigl(\rho_{\mathrm{ss}}(\mu),V_{1+r,\star}\bigr)
\,\leq\,
C_1\exp\Bigl(-C_2 \, r^{1/d}\Bigr)
\qquad\text{for all }r\in\ensuremath\mathbb{N}.
\end{equation*}

\label[proposition]{prop:finite_training_set_convergence}
Suppose the assumptions of \Cref{prop:analytic_width_decay} hold,
and let $\Xi_{\mathrm{train}}\subseteq\mathcal{P}$ be nonempty and finite.
For either formulation $\star\in\{\mathrm{eig},\mathrm{aff}\}$, let
$V_{1+k,\star}^{\Xi}$ denote the space produced by
\Cref{alg:greedy_reduced_basis} after $k$ snapshot enrichments.  
Then, there exist constants $C_1,C_2>0$, 
independent of~$r$ and of the training set, 
such that
\begin{equation}
\sup_{\xi\in\Xi_{\mathrm{train}}}
\mathrm{dist}\bigl(\rho_{\mathrm{ss}}(\xi),V_{1+r,\star}^{\Xi}\bigr)
\,\leq\,
C_1\exp\Bigl(-C_2 r^{1/d}\Bigr)
\label{eq:discrete_training_manifold_convergence}
\end{equation}
for every snapshot enrichment performed by the algorithm.
If the algorithm terminates because $\Xi_{\mathrm{act}}=\emptyset$,
then its final space~$V_{r,\star}^{\Xi}$ additionally satisfies
\begin{equation}
\sup_{\mu\in\mathcal{P}}
\mathrm{dist}\bigl(\rho_{\mathrm{ss}}(\mu),V_{r,\star}^{\Xi}\bigr)
\,\leq\,
\sqrt{C_\star\varepsilon_{\mathrm{tol}}}
+
\delta_\Xi
\,\leq\,
\sqrt{C_\star\varepsilon_{\mathrm{tol}}}
+
L_u h_\Xi,
\label{eq:finite_training_set_stopping_error}
\end{equation}
where
$C_\mathrm{eig}\coloneqq\gamma_{\min}^{-1}$ and
$C_\mathrm{aff}\coloneqq\beta_{\min}^{-2}$.
